/**
 * CACHE TYPE
 * none (key不存在)
 * string (字符串)
 * list (列表)
 * set (集合)
 * zset (有序集)
 * hash.js (哈希表)
 */
const CACHE_TYPE = {
  NONE: 'none',
  STRING: 'string',
  LIST: 'list',
  SET: 'set',
  ZSET: 'zset',
  HASH: 'hash',
};

/**
 * CACHE_ERROR
 * WRONGTYPE (对key使用错误的类型操作)
 * NOT_INT (入参或者Cache中的Value类型不为整数)
 */
const CACHE_ERROR = {
  WRONGTYPE: 'WRONGTYPE Operation against a key holding the wrong kind of value',
  NOT_INT: 'ERR value is not an integer or out of range',
};

/**
 * list linsert 插入方向常量
 * @type {{BEFORE: string, AFTER: string}}
 */
const CACHE_DIRECTION = {
  BEFORE: 'BEFORE',
  AFTER: 'AFTER',
};

/**
 * 入参常量
 * @type {{WITHSCORES: string, LIMIT: string}}
 */
const CACHE_CONSTANT = {
  WITHSCORES: 'WITHSCORES',
  LIMIT: 'LIMIT',
  FORCEMASTER: 'FORCEMASTER',
};

// DCache乐观锁默认重试次数
const RETRY = 3;

module.exports = {
  RETRY,

  TYPE: CACHE_TYPE,

  DIRECTION: CACHE_DIRECTION,

  CONSTANT: CACHE_CONSTANT,

  ERROR: CACHE_ERROR,
};
